#!/usr/bin/env python3
"""Driver: build diagram, run ditaa --svg, parse path d attrs."""
import os, re, subprocess, tempfile, hashlib
from concurrent.futures import ThreadPoolExecutor

EXE = "/workspace/executable"
CACHE = "/tmp/vertexorder/cache"
os.makedirs(CACHE, exist_ok=True)

CELLW, CELLH = 10, 14

def cell_center(c, r):
    return ((c + 2) * CELLW + CELLW // 2, (r + 2) * CELLH + CELLH // 2)

PATH_RE = re.compile(r"<path([^>]*)/>")
D_RE = re.compile(r"d='([^']*)'")

def run(text, args=("--svg",), use_cache=True):
    key = hashlib.sha1((repr(args) + "\n" + text).encode()).hexdigest()
    cf = os.path.join(CACHE, key + ".svg")
    if use_cache and os.path.exists(cf):
        return open(cf).read()
    with tempfile.TemporaryDirectory() as d:
        inp = os.path.join(d, "in.txt")
        out = os.path.join(d, "out.svg")
        with open(inp, "w") as f:
            f.write(text)
        subprocess.run([EXE, inp, out] + list(args), stdout=subprocess.DEVNULL,
                       stderr=subprocess.DEVNULL, check=False)
        svg = open(out).read() if os.path.exists(out) else ""
    with open(cf, "w") as f:
        f.write(svg)
    return svg

def paths(svg):
    """Return list of (attrs, d) for each <path>."""
    res = []
    for m in PATH_RE.finditer(svg):
        attrs = m.group(1)
        dm = D_RE.search(attrs)
        if dm:
            res.append((attrs, dm.group(1)))
    return res

def parse_d(d):
    """Return (list of (x,y) floats, closed_bool). Handles M/L/C/z."""
    toks = d.replace(",", " ").split()
    pts = []
    closed = False
    i = 0
    while i < len(toks):
        t = toks[i]
        if t in ("M", "L"):
            pts.append((float(toks[i + 1]), float(toks[i + 2])))
            i += 3
        elif t == "C":
            pts.append(("C", float(toks[i + 1]), float(toks[i + 2]),
                        float(toks[i + 3]), float(toks[i + 4]),
                        float(toks[i + 5]), float(toks[i + 6])))
            i += 7
        elif t in ("z", "Z"):
            closed = True
            i += 1
        else:
            i += 1
    return pts, closed

def runmany(texts, workers=12):
    with ThreadPoolExecutor(workers) as ex:
        return list(ex.map(run, texts))

def box(cx, cy, w, h, W=None, H=None):
    """3x3 (w=h=3) style closed box, top-left char at (cx,cy). Returns text lines."""
    lines = []
    for r in range(h):
        if r == 0 or r == h - 1:
            lines.append(" " * cx + "+" + "-" * (w - 2) + "+")
        else:
            lines.append(" " * cx + "|" + " " * (w - 2) + "|")
    out = [""] * cy + lines
    return "\n".join(out) + "\n"

CORNER_NAMES = {}

def classify_rect(pts, x0, y0, x1, y1):
    """pts: list of (x,y). Rect corners TL=(x0,y0) TR=(x1,y0) BR=(x1,y1) BL=(x0,y1).
    Return string like 'TL,BL,BR,TR'."""
    names = []
    for p in pts:
        if not isinstance(p[0], float):
            names.append("?")
            continue
        x, y = p
        v = ("T" if abs(y - y0) < 0.01 else ("B" if abs(y - y1) < 0.01 else "?"))
        u = ("L" if abs(x - x0) < 0.01 else ("R" if abs(x - x1) < 0.01 else "?"))
        names.append(v + u)
    return ",".join(names)

if __name__ == "__main__":
    import sys
    t = box(0, 0, 3, 3)
    svg = run(t)
    for a, d in paths(svg):
        print(d)

#!/usr/bin/env python3
"""Sweep isolated boxes of given size over a lattice of positions, packed many per diagram."""
import sys, json
import drv
from drv import cell_center, run, paths, parse_d
from concurrent.futures import ThreadPoolExecutor

def make_diagram(positions, w, h):
    """positions: list of (cx,cy). Return text."""
    maxc = max(cx + w for cx, cy in positions)
    maxr = max(cy + h for cx, cy in positions)
    grid = [[" "] * (maxc + 1) for _ in range(maxr + 1)]
    for cx, cy in positions:
        for r in range(h):
            for c in range(w):
                ch = " "
                if r in (0, h - 1) and c in (0, w - 1):
                    ch = "+"
                elif r in (0, h - 1):
                    ch = "-"
                elif c in (0, w - 1):
                    ch = "|"
                if ch != " ":
                    grid[cy + r][cx + c] = ch
    return "\n".join("".join(row).rstrip() for row in grid) + "\n"

def order_string(pts, cx, cy, w, h):
    x0, y0 = cell_center(cx, cy)
    x1, y1 = cell_center(cx + w - 1, cy + h - 1)
    return drv.classify_rect(pts, x0, y0, x1, y1)

def sweep(w, h, cmax=32, rmax=32, gap=None, workers=12):
    if gap is None:
        gap = max(w, h) + 4
    tasks = []
    for a in range(gap):
        for b in range(gap):
            pos = [(cx, cy) for cx in range(a, cmax, gap) for cy in range(b, rmax, gap)]
            if pos:
                tasks.append(pos)
    texts = [make_diagram(p, w, h) for p in tasks]
    with ThreadPoolExecutor(workers) as ex:
        svgs = list(ex.map(run, texts))
    result = {}
    for pos, svg in zip(tasks, svgs):
        ps = paths(svg)
        # dedupe: shadow + fill pairs -> take unique d per bbox, but verify identical
        seen = {}
        for attrs, d in ps:
            pts, closed = parse_d(d)
            xs = [p[0] for p in pts if isinstance(p[0], float)]
            ys = [p[1] for p in pts if isinstance(p[0], float)]
            if not xs:
                continue
            key = (min(xs), min(ys), max(xs), max(ys))
            seen.setdefault(key, []).append((d, pts, closed))
        for cx, cy in pos:
            x0, y0 = cell_center(cx, cy)
            x1, y1 = cell_center(cx + w - 1, cy + h - 1)
            key = (float(x0), float(y0), float(x1), float(y1))
            if key not in seen:
                result[(cx, cy)] = "MISSING"
                continue
            ds = set(x[0] for x in seen[key])
            if len(ds) != 1:
                result[(cx, cy)] = "AMBIG:" + "|".join(sorted(ds))
                continue
            d, pts, closed = seen[key][0]
            result[(cx, cy)] = order_string(pts, cx, cy, w, h)
    return result

if __name__ == "__main__":
    w = int(sys.argv[1]); h = int(sys.argv[2])
    cmax = int(sys.argv[3]) if len(sys.argv) > 3 else 32
    rmax = int(sys.argv[4]) if len(sys.argv) > 4 else 32
    res = sweep(w, h, cmax, rmax)
    out = {}
    for (cx, cy), v in sorted(res.items()):
        out[f"{cx},{cy}"] = v
    with open(f"/tmp/vertexorder/sweep_{w}x{h}.json", "w") as f:
        json.dump(out, f, indent=0)
    # print grid
    codes = {}
    print(f"=== box {w}x{h} : rows=cy 0..{rmax-1}, cols=cx 0..{cmax-1}")
    for cy in range(rmax):
        row = []
        for cx in range(cmax):
            v = res.get((cx, cy), "-")
            if v not in codes:
                codes[v] = chr(ord('a') + len(codes))
            row.append(codes[v])
        print(f"cy={cy:2d} " + "".join(row))
    for k, v in sorted(codes.items(), key=lambda kv: kv[1]):
        print(v, "=", k)

#!/usr/bin/env python3
import json, sys, glob

def load(name):
    d = json.load(open(name))
    return {tuple(int(t) for t in k.split(",")): v for k, v in d.items()}

def periods(m):
    cs = sorted(set(k[0] for k in m))
    rs = sorted(set(k[1] for k in m))
    res = {}
    for axis, vals in (("cx", cs), ("cy", rs)):
        found = None
        for p in (1, 2, 4, 8, 16, 32, 64):
            ok = True
            for (cx, cy), v in m.items():
                k2 = (cx + p, cy) if axis == "cx" else (cx, cy + p)
                if k2 in m and m[k2] != v:
                    ok = False
                    break
            if ok:
                found = p
                break
        res[axis] = found
    return res

for f in sorted(glob.glob("/tmp/vertexorder/sweep_*.json")):
    m = load(f)
    vals = sorted(set(m.values()))
    print(f.split("/")[-1], "n=", len(m), "periods=", periods(m), "distinct=", len(vals))
    print("   ", vals)

#!/usr/bin/env python3
"""Generic shape sweep: place a shape template at many (cx,cy), report vertex seq
as relative cell coordinates."""
import sys, json
import drv
from drv import run, paths, parse_d
from concurrent.futures import ThreadPoolExecutor

def cell_of(x, y):
    """inverse of cell_center"""
    c = (x - 25.0) / 10.0
    r = (y - 35.0) / 14.0
    return (c, r)

def place(tmpl, positions):
    h = len(tmpl)
    w = max(len(l) for l in tmpl)
    maxc = max(cx for cx, cy in positions) + w
    maxr = max(cy for cx, cy in positions) + h
    grid = [[" "] * (maxc + 2) for _ in range(maxr + 2)]
    for cx, cy in positions:
        for r, line in enumerate(tmpl):
            for c, ch in enumerate(line):
                if ch != " ":
                    grid[cy + r][cx + c] = ch
    return "\n".join("".join(row).rstrip() for row in grid) + "\n"

def sweep_shape(tmpl, cmax=32, rmax=32, gap=None, workers=12, tag="shape"):
    h = len(tmpl); w = max(len(l) for l in tmpl)
    if gap is None:
        gap = max(w, h) + 4
    tasks = []
    for a in range(gap):
        for b in range(gap):
            pos = [(cx, cy) for cx in range(a, cmax, gap) for cy in range(b, rmax, gap)]
            if pos:
                tasks.append(pos)
    texts = [place(tmpl, p) for p in tasks]
    with ThreadPoolExecutor(workers) as ex:
        svgs = list(ex.map(run, texts))
    result = {}
    for pos, svg in zip(tasks, svgs):
        groups = {}
        for attrs, d in paths(svg):
            pts, closed = parse_d(d)
            cells = [cell_of(p[0], p[1]) for p in pts if isinstance(p[0], float)]
            if not cells:
                continue
            key = (min(c for c, r in cells), min(r for c, r in cells))
            groups.setdefault(key, []).append((cells, closed))
        for cx, cy in pos:
            # find group whose bbox min matches shape's min corner offsets
            # compute expected bbox of vertices: min over template non-space
            occ = [(c, r) for r, line in enumerate(tmpl) for c, ch in enumerate(line) if ch != " "]
            mc = cx + min(c for c, r in occ)
            mr = cy + min(r for c, r in occ)
            key = (float(mc), float(mr))
            if key not in groups:
                result[(cx, cy)] = "MISSING"
                continue
            uniq = set(tuple(g[0]) for g in groups[key])
            if len(uniq) != 1:
                result[(cx, cy)] = "AMBIG"
                continue
            cells, closed = groups[key][0]
            rel = [(int(round(c - cx)), int(round(r - cy))) for c, r in cells]
            result[(cx, cy)] = ("Z" if closed else "O") + " " + " ".join(f"{a},{b}" for a, b in rel)
    return result

def report(tmpl, res, cmax, rmax, label):
    codes = {}
    lines = []
    lines.append(f"=== {label}")
    for l in tmpl:
        lines.append("   |" + l)
    for cy in range(rmax):
        row = []
        for cx in range(cmax):
            v = res.get((cx, cy), "-")
            if v not in codes:
                codes[v] = chr(ord('a') + len(codes)) if len(codes) < 26 else chr(ord('A') + len(codes) - 26)
            row.append(codes[v])
        lines.append(f"cy={cy:2d} " + "".join(row))
    for k, v in sorted(codes.items(), key=lambda kv: kv[1]):
        lines.append(f"  {v} = {k}")
    return "\n".join(lines)

if __name__ == "__main__":
    name = sys.argv[1]
    cmax = int(sys.argv[2]) if len(sys.argv) > 2 else 32
    rmax = int(sys.argv[3]) if len(sys.argv) > 3 else 32
    SHAPES = {
        "b2": ["++", "++"],
        "b3": ["+-+", "| |", "+-+"],
        "b43": ["+--+", "|  |", "+--+"],
        "b63": ["+----+", "|    |", "+----+"],
        "b53": ["+---+", "|   |", "+---+"],
        "b34": ["+-+", "| |", "| |", "+-+"],
        "b55": ["+---+", "|   |", "|   |", "|   |", "+---+"],
        "L": ["+-+", "| +-+", "+---+"],
        "L2": ["+--+", "|  |", "|  +--+", "|     |", "+-----+"],
        "plus": ["  +-+", "  | |", "+-+ +-+", "|     |", "+-+ +-+", "  | |", "  +-+"],
        "stair": ["+-+", "| +-+", "+-+ |", "  +-+"],
        "b23": ["++", "||", "++"],
        "b32": ["+-+", "+-+"],
        "b24": ["++", "||", "||", "++"],
        "b42": ["+--+", "+--+"],
    }
    tmpl = SHAPES[name]
    res = sweep_shape(tmpl, cmax, rmax)
    out = {f"{cx},{cy}": v for (cx, cy), v in sorted(res.items())}
    json.dump(out, open(f"/tmp/vertexorder/sh_{name}.json", "w"), indent=0)
    print(report(tmpl, res, cmax, rmax, name))

#!/usr/bin/env python3
"""Fit the bucket/hash function from pair probes (h2, v2)."""
import json, itertools, struct

M32 = 0xFFFFFFFF

def s32(v):
    v &= M32
    return v - (1 << 32) if v >= (1 << 31) else v

def bucket(h, cap):
    h &= M32
    return (h ^ (h >> 16)) & (cap - 1)

def load(name):
    d = json.load(open(f"/tmp/vertexorder/sh_{name}.json"))
    return {tuple(int(t) for t in k.split(",")): v for k, v in d.items()}

h2 = load("h2")
v2 = load("v2")

# a-code strings
def first_is_origin(v):
    # v like "O 0,0 1,0"
    parts = v.split()
    return parts[1] == "0,0"

H = {}
V = {}
for (x, y), v in h2.items():
    H[(x % 16, y % 16)] = first_is_origin(v)   # True => B(x,y) <= B(x+1,y)
for (x, y), v in v2.items():
    V[(x % 16, y % 16)] = first_is_origin(v)   # True => B(x,y) <= B(x,y+1)

# check consistency of period-16 reduction
def chk(tbl, src, fn):
    bad = 0
    for (x, y), v in src.items():
        if tbl[(x % 16, y % 16)] != fn(v):
            bad += 1
    return bad
print("period-16 violations H:", chk(H, h2, first_is_origin), "V:", chk(V, v2, first_is_origin))

def show(tbl, name):
    print(f"--- {name} (rows y=0..15, cols x=0..15): a = B(cell)<=B(next)")
    for y in range(16):
        print(f"y={y:2d} " + "".join("a" if tbl[(x, y)] else "b" for x in range(16)))

show(H, "H  (compare (x,y) vs (x+1,y))")
show(V, "V  (compare (x,y) vs (x,y+1))")
